const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Dublin geometry (centered on Dublin city, ~20km buffer)
  const dublin = ee.Geometry.Point([-6.2603, 53.3498]).buffer(20000); // 20km buffer

  // 2. Define time periods
  const start1984 = '1984-11-01';
  const end1984 = '1984-11-30';
  const start2022 = '2022-11-01';
  const end2022 = '2022-11-30';

  // Function to mask clouds for Landsat 5
  function maskL5Clouds(image) {
    const qa = image.select('pixel_qa');
    // Bits: 3 = cloud, 4 = cloud shadow
    const cloudBitMask = 1 << 3;
    const shadowBitMask = 1 << 4;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(shadowBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Function to mask clouds for Landsat 8
  function maskL8Clouds(image) {
    const qa = image.select('QA_PIXEL');
    const cloudBitMask = 1 << 3;
    const shadowBitMask = 1 << 4;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(shadowBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Function to calculate NDBI for Landsat 5
  function addNDBI_L5(image) {
    // NDBI = (SWIR - NIR) / (SWIR + NIR)
    // Landsat 5: SWIR = Band 5, NIR = Band 4
    const ndbi = image.normalizedDifference(['B5', 'B4']).rename('NDBI');
    return image.addBands(ndbi);
  }

  // Function to calculate NDBI for Landsat 8
  function addNDBI_L8(image) {
    // Landsat 8: SWIR = Band 6, NIR = Band 5
    const ndbi = image.normalizedDifference(['B6', 'B5']).rename('NDBI');
    return image.addBands(ndbi);
  }

  // 3. Get Landsat 5 collection for 1984
  let l5Col = ee.ImageCollection('LANDSAT/LT05/C02/T1_TOA')
    .filterBounds(dublin)
    .filterDate(start1984, end1984);

  let l5Size = l5Col.size().getInfo();
  console.log(`1984 Images: ${l5Size}`);

  // 4. Get Landsat 8 collection for 2022
  let l8Col = ee.ImageCollection('LANDSAT/LC08/C02/T1_TOA')
    .filterBounds(dublin)
    .filterDate(start2022, end2022);

  let l8Size = l8Col.size().getInfo();
  console.log(`2022 Images: ${l8Size}`);

  // 5. Check if collections are empty - try fallbacks if needed
  if (l5Size === 0) {
    // Try widening the date range for 1984 (full year 1984-1985)
    l5Col = ee.ImageCollection('LANDSAT/LT05/C02/T1_TOA')
      .filterBounds(dublin)
      .filterDate('1984-01-01', '1985-12-31');
    l5Size = l5Col.size().getInfo();
    console.log(`1984-1985 Images: ${l5Size}`);
  }

  if (l8Size === 0) {
    // Try widening the date range for 2022 (2021-2023)
    l8Col = ee.ImageCollection('LANDSAT/LC08/C02/T1_TOA')
      .filterBounds(dublin)
      .filterDate('2021-01-01', '2023-12-31');
    l8Size = l8Col.size().getInfo();
    console.log(`2021-2023 Images: ${l8Size}`);
  }

  // Final check: if either collection is empty, output C1
  if (l5Size === 0 || l8Size === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 6. Process the collections
  const l5Processed = l5Col
    .map(maskL5Clouds)
    .map(addNDBI_L5)
    .select('NDBI')
    .median();

  const l8Processed = l8Col
    .map(maskL8Clouds)
    .map(addNDBI_L8)
    .select('NDBI')
    .median();

  // 7. Check valid pixel counts
  const count1984 = l5Processed.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: dublin,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDBI').getInfo();

  const count2022 = l8Processed.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: dublin,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDBI').getInfo();

  console.log(`1984 Valid Pixels: ${count1984}`);
  console.log(`2022 Valid Pixels: ${count2022}`);

  if (count1984 === 0 || count2022 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 8. Calculate mean NDBI values
  const mean1984 = l5Processed.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: dublin,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDBI').getInfo();

  const mean2022 = l8Processed.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: dublin,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDBI').getInfo();

  console.log(`1984 Mean NDBI: ${mean1984 ? mean1984.toFixed(4) : 'null'}`);
  console.log(`2022 Mean NDBI: ${mean2022 ? mean2022.toFixed(4) : 'null'}`);

  // 9. Validate results
  if (mean1984 === null || mean2022 === null || 
      isNaN(mean1984) || isNaN(mean2022) ||
      Math.abs(mean1984) > 1 || Math.abs(mean2022) > 1) {
    console.log("<answer>C3</answer>");
    return;
  }

  // 10. Compare and output final answer
  if (mean2022 > mean1984) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
